//! Runtime integrity of the bundled interpreter and SYNCODE core.
//!
//! The trust anchor is `BUNDLE_FILES`, generated by `build.rs` and compiled
//! into the executable: a manifest beside the runtime could be rewritten by
//! whoever can rewrite the runtime, this table cannot.
//!
//! Before any command runs, [`pin`]:
//! * requires the exact set of files under `python/` and `syncode/` (no
//!   missing and no extra file: a planted `python/transaction.py` would shadow
//!   the core because `._pth` lists `.` before `..\syncode\scripts`);
//! * rejects reparse points (symlinks/junctions) and paths that resolve
//!   outside the resource directory;
//! * opens every file allowing only shared *reads* and hashes it through that
//!   same handle. The handles stay open in [`Pinned`] until the child process
//!   has exited: verified files cannot be modified, replaced or deleted
//!   meanwhile. New files created after the second enumeration are not
//!   prevented (an actor with the user's rights can also replace the exe);
//!   see ADR-0009 for this residual risk.

use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::fs::File;
use std::io::Read;
use std::path::{Path, PathBuf};

include!(concat!(env!("OUT_DIR"), "/integrity_table.rs"));

const TREES: [&str; 2] = ["python", "syncode"];

/// Open handles that keep the verified files immutable while held.
#[derive(Debug)]
pub struct Pinned {
    #[allow(dead_code)] // held for their sharing mode, never read again
    handles: Vec<File>,
    pub files: usize,
}

/// Verify `dir` against the table compiled into this executable.
pub fn pin(dir: &Path) -> Result<Pinned, String> {
    pin_with(dir, BUNDLE_FILES)
}

/// Verify `dir` against an explicit table (tests use synthetic tables).
pub fn pin_with(dir: &Path, table: &[(&str, &str)]) -> Result<Pinned, String> {
    if table.is_empty() {
        return Err(
            "this build has no embedded integrity table (runtime not staged at build time)".into(),
        );
    }
    let root = dir
        .canonicalize()
        .map_err(|e| format!("resource directory unavailable: {e}"))?;
    let expected: BTreeMap<&str, &str> = table.iter().copied().collect();

    // 0. CPython's startup reads `pyvenv.cfg` (and `._pth`) next to the
    //    interpreter *and in its parent*, which is this unverified folder.
    for entry in std::fs::read_dir(&root).map_err(|e| e.to_string())? {
        let name = entry.map_err(|e| e.to_string())?.file_name();
        let name = name.to_string_lossy().to_ascii_lowercase();
        if name == "pyvenv.cfg" || name.ends_with(".pth") || name.ends_with("._pth") {
            return Err(format!(
                "unexpected interpreter configuration next to the bundle: {name}"
            ));
        }
    }

    // 1. Exact file set, no reparse points anywhere in the trees.
    let found = enumerate(&root)?;
    let extra: Vec<&String> = found
        .iter()
        .filter(|rel| !expected.contains_key(rel.as_str()))
        .collect();
    if !extra.is_empty() {
        return Err(format!("unexpected files in the bundle: {}", list(&extra)));
    }
    let missing: Vec<&&str> = expected
        .keys()
        .filter(|rel| !found.iter().any(|f| f == *rel))
        .collect();
    if !missing.is_empty() {
        return Err(format!("missing bundle files: {}", list(&missing)));
    }

    // 2. Hash every file through a handle that refuses writers and deleters.
    let mut handles = Vec::with_capacity(expected.len());
    for (rel, digest) in &expected {
        let path = rel.split('/').fold(root.clone(), |p, part| p.join(part));
        let mut file = open_pinned(&path).map_err(|e| format!("{rel}: {e}"))?;
        let resolved = path.canonicalize().map_err(|e| format!("{rel}: {e}"))?;
        if !resolved.starts_with(&root) {
            return Err(format!("{rel} resolves outside the bundle"));
        }
        let mut hasher = Sha256::new();
        let mut buf = vec![0u8; 1 << 16];
        loop {
            let n = file.read(&mut buf).map_err(|e| format!("{rel}: {e}"))?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        let actual = hex(&hasher.finalize());
        if actual != *digest {
            return Err(format!("{rel} was modified"));
        }
        handles.push(file);
    }

    // 3. Nothing appeared between the walk and the pinning (a new module in
    //    an import directory would be loaded although it was never hashed).
    if enumerate(&root)? != found {
        return Err("the bundle changed while it was being verified".into());
    }
    Ok(Pinned {
        files: handles.len(),
        handles,
    })
}

fn enumerate(root: &Path) -> Result<Vec<String>, String> {
    let mut found = Vec::new();
    for tree in TREES {
        walk(root, &root.join(tree), &mut found)?;
    }
    found.sort();
    Ok(found)
}

fn list<T: std::fmt::Display>(items: &[T]) -> String {
    let shown: Vec<String> = items.iter().take(5).map(|i| i.to_string()).collect();
    let more = items.len().saturating_sub(shown.len());
    if more > 0 {
        format!("{} (+{more})", shown.join(", "))
    } else {
        shown.join(", ")
    }
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn is_reparse(meta: &std::fs::Metadata) -> bool {
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;
        const FILE_ATTRIBUTE_REPARSE_POINT: u32 = 0x400;
        meta.file_attributes() & FILE_ATTRIBUTE_REPARSE_POINT != 0
    }
    #[cfg(not(windows))]
    {
        meta.file_type().is_symlink()
    }
}

fn walk(root: &Path, dir: &Path, found: &mut Vec<String>) -> Result<(), String> {
    let meta = std::fs::symlink_metadata(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    if is_reparse(&meta) || !meta.is_dir() {
        return Err(format!("{} is not a plain directory", rel_of(root, dir)));
    }
    for entry in std::fs::read_dir(dir).map_err(|e| e.to_string())? {
        let path = entry.map_err(|e| e.to_string())?.path();
        let meta = std::fs::symlink_metadata(&path).map_err(|e| e.to_string())?;
        if is_reparse(&meta) {
            return Err(format!("{} is a link or junction", rel_of(root, &path)));
        }
        if meta.is_dir() {
            walk(root, &path, found)?;
        } else if meta.is_file() {
            found.push(rel_of(root, &path));
        } else {
            return Err(format!("{} is not a regular file", rel_of(root, &path)));
        }
    }
    Ok(())
}

fn rel_of(root: &Path, path: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or(path)
        .components()
        .map(|c| c.as_os_str().to_string_lossy().into_owned())
        .collect::<Vec<_>>()
        .join("/")
}

/// Read-only handle that lets others read/execute but not write or delete.
fn open_pinned(path: &PathBuf) -> std::io::Result<File> {
    let mut options = std::fs::OpenOptions::new();
    options.read(true);
    #[cfg(windows)]
    {
        use std::os::windows::fs::OpenOptionsExt;
        const FILE_SHARE_READ: u32 = 0x1;
        const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
        options.share_mode(FILE_SHARE_READ);
        // Never follow a reparse point swapped in after the directory walk.
        options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
    }
    let file = options.open(path)?;
    if is_reparse(&file.metadata()?) {
        return Err(std::io::Error::other("is a link or junction"));
    }
    Ok(file)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::runner::testing::{copy_tree, scratch, staged};

    fn sha(data: &[u8]) -> String {
        hex(&Sha256::digest(data))
    }

    fn fixture(name: &str) -> (PathBuf, Vec<(String, String)>) {
        let dir = scratch(name);
        let files: [(&str, &[u8]); 5] = [
            ("python/python.exe", b"MZ".as_slice()),
            (
                "python/python312._pth",
                b"python312.zip\n.\n..\\syncode\\scripts\n",
            ),
            ("syncode/scripts/sync.py", b"print('sync')\n"),
            ("syncode/scripts/plan_identity.py", b"X = 1\n"),
            ("syncode/BUNDLE_MANIFEST.json", b"{}\n"),
        ];
        let mut table = Vec::new();
        for (rel, data) in files {
            let path = rel.split('/').fold(dir.clone(), |p, part| p.join(part));
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, data).unwrap();
            table.push((rel.to_string(), sha(data)));
        }
        (dir, table)
    }

    fn check(dir: &Path, table: &[(String, String)]) -> Result<Pinned, String> {
        let refs: Vec<(&str, &str)> = table
            .iter()
            .map(|(a, b)| (a.as_str(), b.as_str()))
            .collect();
        pin_with(dir, &refs)
    }

    #[test]
    fn intact_bundle_is_pinned() {
        let (dir, table) = fixture("integrity-ok");
        assert_eq!(check(&dir, &table).unwrap().files, 5);
    }

    #[test]
    fn empty_table_never_verifies() {
        let (dir, _) = fixture("integrity-empty");
        assert!(pin_with(&dir, &[]).is_err());
    }

    #[test]
    fn modified_entry_point_module_and_manifest_are_rejected() {
        for rel in [
            "syncode/scripts/sync.py",
            "syncode/scripts/plan_identity.py",
            "syncode/BUNDLE_MANIFEST.json",
            "python/python312._pth",
        ] {
            let (dir, table) = fixture("integrity-mod");
            let path = rel.split('/').fold(dir.clone(), |p, part| p.join(part));
            let mut data = std::fs::read(&path).unwrap();
            data.extend_from_slice(b"\n# tampered\n");
            std::fs::write(&path, data).unwrap();
            let error = check(&dir, &table).unwrap_err();
            assert!(error.contains(rel) && error.contains("modified"), "{error}");
        }
    }

    #[test]
    fn missing_and_extra_files_are_rejected() {
        let (dir, table) = fixture("integrity-missing");
        std::fs::remove_file(dir.join("syncode/scripts/plan_identity.py")).unwrap();
        assert!(check(&dir, &table).unwrap_err().contains("missing"));

        // A planted module next to python.exe would shadow the core.
        let (dir, table) = fixture("integrity-extra");
        std::fs::write(dir.join("python/transaction.py"), b"evil").unwrap();
        assert!(check(&dir, &table)
            .unwrap_err()
            .contains("python/transaction.py"));
        let (dir, table) = fixture("integrity-extra2");
        std::fs::write(dir.join("python/pyvenv.cfg"), b"home = C:\\evil").unwrap();
        assert!(check(&dir, &table).unwrap_err().contains("unexpected"));
    }

    #[test]
    fn interpreter_configuration_next_to_the_bundle_is_rejected() {
        for name in ["pyvenv.cfg", "python312._pth", "evil.pth"] {
            let (dir, table) = fixture("integrity-root");
            std::fs::write(dir.join(name), b"home = C:/evil\n").unwrap();
            assert!(
                check(&dir, &table)
                    .unwrap_err()
                    .contains("interpreter configuration"),
                "{name}"
            );
        }
    }

    #[test]
    fn planted_bytecode_cache_is_rejected() {
        let (dir, table) = fixture("integrity-pyc");
        std::fs::create_dir_all(dir.join("syncode/scripts/__pycache__")).unwrap();
        std::fs::write(
            dir.join("syncode/scripts/__pycache__/sync.cpython-312.pyc"),
            b"x",
        )
        .unwrap();
        assert!(check(&dir, &table).unwrap_err().contains("__pycache__"));
    }

    #[cfg(windows)]
    #[test]
    fn junctions_are_rejected() {
        let (dir, table) = fixture("integrity-junction");
        let outside = scratch("integrity-outside");
        std::fs::write(outside.join("sync.py"), b"print('sync')\n").unwrap();
        std::fs::remove_dir_all(dir.join("syncode/scripts")).unwrap();
        std::fs::create_dir_all(dir.join("syncode")).unwrap();
        let status = std::process::Command::new("cmd")
            .args(["/C", "mklink", "/J"])
            .arg(dir.join("syncode").join("scripts"))
            .arg(&outside)
            .output()
            .unwrap();
        assert!(status.status.success(), "{status:?}");
        assert!(check(&dir, &table).unwrap_err().contains("junction"));
    }

    #[cfg(windows)]
    #[test]
    fn pinned_files_cannot_be_modified_or_deleted() {
        let (dir, table) = fixture("integrity-pinned");
        let pinned = check(&dir, &table).unwrap();
        let target = dir.join("syncode/scripts/sync.py");
        assert!(std::fs::OpenOptions::new()
            .append(true)
            .open(&target)
            .is_err());
        assert!(std::fs::remove_file(&target).is_err());
        assert!(std::fs::read(&target).is_ok(), "readers are still allowed");
        drop(pinned);
        assert!(std::fs::OpenOptions::new()
            .append(true)
            .open(&target)
            .is_ok());
    }

    #[test]
    fn embedded_table_matches_the_staged_bundle_and_detects_tampering() {
        let Some(runtime) = staged() else { return };
        assert!(!BUNDLE_FILES.is_empty());
        assert!(pin(&runtime.workdir).is_ok());
        let copy = scratch("integrity-embedded");
        for tree in TREES {
            copy_tree(&runtime.workdir.join(tree), &copy.join(tree));
        }
        assert!(pin(&copy).is_ok());
        let sync = copy.join("syncode").join("scripts").join("sync.py");
        let mut data = std::fs::read(&sync).unwrap();
        data.extend_from_slice(b"\nimport os\n");
        std::fs::write(&sync, data).unwrap();
        assert!(pin(&copy).unwrap_err().contains("syncode/scripts/sync.py"));
    }
}
